from flask import Flask, request, jsonify, g
import psycopg2
import os

app = Flask(__name__)

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=os.environ.get('DB_HOST', 'postgres.database.svc.cluster.local'),
            database=os.environ.get('DB_NAME', 'orders'),
            user=os.environ.get('DB_USER', 'orderservice'),
            password=os.environ.get('DB_PASS', '')
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def get_current_user_id():
    """Extract user ID from X-User-Id header set by API gateway"""
    return request.headers.get('X-User-Id')

def get_requesting_namespace():
    """Extract source namespace from Envoy metadata header"""
    return request.headers.get('X-Source-Namespace', 'unknown')

@app.route('/api/v1/orders/<order_id>', methods=['GET'])
def get_order(order_id):
    """Fetch order by ID. Authorization relies on service mesh layer."""
    db = get_db()
    cursor = db.cursor()
    # VULNERABILITY: No ownership check - any authenticated user can access any order
    # The order_id is directly used without verifying it belongs to the requesting user
    cursor.execute(
        "SELECT id, user_id, product_name, quantity, total_price, status, created_at "
        "FROM orders WHERE id = %s",
        (order_id,)
    )
    row = cursor.fetchone()
    if not row:
        return jsonify({'error': 'Order not found'}), 404

    order = {
        'id': row[0],
        'user_id': row[1],
        'product_name': row[2],
        'quantity': row[3],
        'total_price': float(row[4]),
        'status': row[5],
        'created_at': row[6].isoformat()
    }
    return jsonify(order), 200

@app.route('/api/v1/orders', methods=['POST'])
def create_order():
    """Create a new order for the authenticated user."""
    user_id = get_current_user_id()
    if not user_id:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    if not data or 'product_name' not in data or 'quantity' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    cursor = db.cursor()
    cursor.execute(
        "INSERT INTO orders (user_id, product_name, quantity, total_price, status) "
        "VALUES (%s, %s, %s, %s, 'pending') RETURNING id",
        (user_id, data['product_name'], data['quantity'], data.get('total_price', 0))
    )
    order_id = cursor.fetchone()[0]
    db.commit()
    return jsonify({'id': order_id, 'status': 'pending'}), 201

@app.route('/api/v1/users/<user_id>/orders', methods=['GET'])
def get_user_orders(user_id):
    """Get all orders for a specific user. No ownership verification."""
    db = get_db()
    cursor = db.cursor()
    # VULNERABILITY: Any caller can enumerate another user's orders
    cursor.execute(
        "SELECT id, product_name, quantity, total_price, status, created_at "
        "FROM orders WHERE user_id = %s ORDER BY created_at DESC",
        (user_id,)
    )
    rows = cursor.fetchall()
    orders = [{
        'id': r[0],
        'product_name': r[1],
        'quantity': r[2],
        'total_price': float(r[3]),
        'status': r[4],
        'created_at': r[5].isoformat()
    } for r in rows]
    return jsonify({'orders': orders, 'count': len(orders)}), 200

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
